components.css:
.ds-btn-primary { box-sizing: border-box;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 44px; padding: 0 20px; border: 1px solid var(--primary, #4e6b48);
  border-radius: var(--control-radius, 2px);
  background: var(--primary, #4e6b48); color: var(--on-primary, #fffaf2);
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); font-size: 14px; font-weight: 600; line-height: 1.43;
  text-decoration: none; cursor: pointer; touch-action: manipulation;
  transition: background-color 150ms cubic-bezier(0.2, 0, 0, 1), border-color 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn-primary:hover { background: var(--primary-hover, #445e3f); border-color: var(--primary-hover, #445e3f); }
.ds-btn-primary:active { background: var(--primary-active, #3a5136); border-color: var(--primary-active, #3a5136); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--focus-ring, #2a1f17); outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

.ds-btn-secondary { box-sizing: border-box;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 44px; padding: 0 20px; border: 1px solid var(--border-strong, #8a7560);
  border-radius: var(--control-radius, 2px);
  background: transparent; color: var(--text-primary, #2a1f17);
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); font-size: 14px; font-weight: 600; line-height: 1.43;
  text-decoration: none; cursor: pointer; touch-action: manipulation;
  transition: background-color 150ms cubic-bezier(0.2, 0, 0, 1), border-color 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn-secondary:hover { background: var(--surface-muted, #e8dcc8); }
.ds-btn-secondary:active { background: var(--surface-muted, #e8dcc8); border-color: var(--text-secondary, #66554a); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--focus-ring, #2a1f17); outline-offset: 2px; }

.ds-btn-danger { box-sizing: border-box;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 44px; padding: 0 20px; border: 1px solid var(--danger, #a3362a);
  border-radius: var(--control-radius, 2px);
  background: var(--danger, #a3362a); color: var(--on-danger, #fffaf2);
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); font-size: 14px; font-weight: 600; line-height: 1.43;
  cursor: pointer; touch-action: manipulation;
  transition: background-color 150ms cubic-bezier(0.2, 0, 0, 1), border-color 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn-danger:hover { background: var(--danger-hover, #8f2f25); border-color: var(--danger-hover, #8f2f25); }
.ds-btn-danger:focus-visible { outline: 2px solid var(--focus-ring, #2a1f17); outline-offset: 2px; }
.ds-btn-danger:disabled { opacity: 0.5; cursor: not-allowed; }

.ds-field-group { display: grid; gap: 12px; max-width: 420px; font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); }
.ds-label { font-size: 14px; font-weight: 600; line-height: 1.43; color: var(--text-primary, #2a1f17); }
.ds-field { box-sizing: border-box;
  width: 100%; min-height: 44px; padding: 10px 12px;
  border: 1px solid var(--border-strong, #8a7560); border-radius: var(--control-radius, 2px);
  background: var(--surface-muted, #e8dcc8); color: var(--text-primary, #2a1f17);
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); font-size: 16px; line-height: 1.5;
  transition: border-color 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-field::placeholder { color: var(--text-secondary, #66554a); opacity: 1; }
.ds-field:hover:not(:focus) { border-color: var(--text-secondary, #66554a); }
.ds-field:focus-visible { border-color: var(--text-primary, #2a1f17); outline: 2px solid var(--focus-ring, #2a1f17); outline-offset: 2px; }
.ds-help { margin: 0; font-size: 13px; line-height: 1.38; color: var(--text-secondary, #66554a); }

.ds-pill { box-sizing: border-box;
  display: inline-flex; align-items: center; gap: 4px; min-height: 24px; padding: 2px 10px;
  border: 1px solid var(--border, #d9c9b0); border-radius: var(--pill-radius, 999px);
  background: var(--surface, #f3ebdd); color: var(--text-primary, #2a1f17);
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); font-size: 13px; font-weight: 600; line-height: 1.38;
}
.ds-pill svg { width: 12px; height: 12px; flex: none; }
.ds-pill-neutral { color: var(--text-primary, #2a1f17); border-color: var(--border, #d9c9b0); }
.ds-pill-success { color: var(--success, #2c6a4a); border-color: var(--success, #2c6a4a); }
.ds-pill-warning { color: var(--warning, #7f5300); border-color: var(--warning, #7f5300); }
.ds-pill-danger { color: var(--danger, #a3362a); border-color: var(--danger, #a3362a); }

.ds-alert { box-sizing: border-box;
  display: flex; align-items: flex-start; gap: 12px; padding: 12px 16px;
  border: 1px solid var(--border, #d9c9b0); border-radius: var(--control-radius, 2px);
  background: var(--surface, #f3ebdd); color: var(--text-primary, #2a1f17);
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); font-size: 13px; line-height: 1.38;
}
.ds-alert svg { flex: none; margin-top: 1px; }
.ds-alert__title { margin: 0; font-weight: 600; }
.ds-alert__text { margin: 4px 0 0; }
.ds-alert-info { color: var(--gold, #7a5c1c); border-color: var(--gold, #7a5c1c); }
.ds-alert-success { color: var(--success, #2c6a4a); border-color: var(--success, #2c6a4a); }
.ds-alert-warning { color: var(--warning, #7f5300); border-color: var(--warning, #7f5300); }
.ds-alert-danger { color: var(--danger, #a3362a); border-color: var(--danger, #a3362a); }

.ds-invitation { box-sizing: border-box;
  overflow: hidden; border: 1px solid var(--border, #d9c9b0); border-radius: var(--control-radius, 2px);
  background: var(--surface, #f3ebdd); color: var(--text-primary, #2a1f17);
  box-shadow: var(--card-shadow, 0 1px 2px rgba(42,31,23,.10), 0 8px 24px rgba(42,31,23,.08));
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); max-width: 42rem;
}
.ds-invitation__accent { height: 4px; background: var(--primary, #4e6b48); }
.ds-invitation__body { padding: 24px; }
@media (min-width: 640px) { .ds-invitation__body { padding: 40px; } }
.ds-invitation__eyebrow { margin: 0; font-size: 12px; font-weight: 600; line-height: 1.33; letter-spacing: 0.16em; text-transform: uppercase; color: var(--text-secondary, #66554a); }
.ds-invitation__title { margin: 8px 0 0; font-family: var(--font-display-stack, 'Cormorant Garamond', Cormorant, Georgia, serif); font-size: clamp(1.5rem, 3.5vw, 1.875rem); font-weight: 600; line-height: 1.13; color: var(--text-primary, #2a1f17); }
@media (min-width: 640px) { .ds-invitation__title { font-size: clamp(2rem, 5vw, 2.75rem); font-weight: 500; line-height: 1.05; } }
.ds-invitation__meta { margin: 16px 0 0; font-size: 18px; line-height: 1.55; color: var(--text-secondary, #66554a); max-width: 48ch; }
.ds-invitation__meta--plain { margin-top: 0; font-size: 16px; }
.ds-invitation__caption { margin: 4px 0 0; font-size: 13px; line-height: 1.38; color: var(--text-secondary, #66554a); }
.ds-invitation__rule { margin: 32px 0 24px; border-top: 1px solid var(--border, #d9c9b0); }
.ds-invitation__guest { margin: 4px 0 0; font-family: var(--font-display-stack, 'Cormorant Garamond', Cormorant, Georgia, serif); font-size: clamp(1.5rem, 3.5vw, 1.875rem); font-weight: 600; line-height: 1.13; color: var(--text-primary, #2a1f17); }

.ds-event-card { box-sizing: border-box;
  display: flex; flex-direction: column; padding: 0 24px 24px;
  border: 1px solid var(--border, #d9c9b0); border-radius: var(--control-radius, 2px);
  background: var(--surface, #f3ebdd); color: var(--text-primary, #2a1f17);
  box-shadow: var(--card-shadow, 0 1px 2px rgba(42,31,23,.10), 0 8px 24px rgba(42,31,23,.08));
  font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); max-width: 32rem;
}
.ds-event-card__accent { height: 4px; margin: 0 -24px 16px; background: var(--primary, #4e6b48); }
.ds-event-card__eyebrow { margin: 0; font-size: 12px; font-weight: 600; line-height: 1.33; letter-spacing: 0.16em; text-transform: uppercase; color: var(--text-secondary, #66554a); }
.ds-event-card__title { margin: 4px 0 0; font-family: var(--font-display-stack, 'Cormorant Garamond', Cormorant, Georgia, serif); font-size: clamp(1.5rem, 3.5vw, 1.875rem); font-weight: 600; line-height: 1.13; }
.ds-event-card__title a { color: inherit; text-decoration: none; }
.ds-event-card__title a:hover { color: var(--primary, #4e6b48); }
.ds-event-card__meta { margin: 16px 0 0; font-size: 16px; line-height: 1.5; color: var(--text-secondary, #66554a); }
.ds-event-card__meta div { display: flex; gap: 8px; }
.ds-event-card__meta dd { margin: 0; }
.ds-event-card__footer { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; margin-top: auto; padding-top: 16px; border-top: 1px solid var(--border, #d9c9b0); }
.ds-event-card__pills { display: flex; flex-wrap: wrap; gap: 8px; }
.ds-event-card__pill { display: inline-flex; align-items: center; min-height: 24px; padding: 2px 10px; border: 1px solid var(--border, #d9c9b0); border-radius: var(--pill-radius, 999px); background: var(--surface, #f3ebdd); font-size: 13px; font-weight: 600; line-height: 1.38; }
.ds-event-card__pill--warning { color: var(--warning, #7f5300); border-color: var(--warning, #7f5300); }
.ds-event-card__actions { display: flex; align-items: center; gap: 16px; font-size: 14px; font-weight: 600; }
.ds-event-card__actions a { color: var(--text-secondary, #66554a); text-decoration: none; }
.ds-event-card__actions a:hover { color: var(--text-primary, #2a1f17); }
.ds-event-card__actions .ds-event-card__open { color: var(--primary, #4e6b48); }
.ds-event-card__actions .ds-event-card__open:hover { text-decoration: underline; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

.ds-header { box-sizing: border-box; border-bottom: 1px solid var(--border, #d9c9b0); background: var(--background, #fbf6ee); font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); }
.ds-header__inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; max-width: 64rem; margin: 0 auto; padding: 12px 16px; }
.ds-header__brand { display: inline-flex; align-items: center; min-height: 44px; font-family: var(--font-display-stack, 'Cormorant Garamond', Cormorant, Georgia, serif); font-size: 20px; color: var(--text-primary, #2a1f17); text-decoration: none; white-space: nowrap; }
.ds-header__nav { display: flex; align-items: center; gap: 16px; }
.ds-header__nav a { display: inline-flex; align-items: center; min-height: 44px; color: var(--text-secondary, #66554a); font-size: 14px; font-weight: 600; text-decoration: none; }
.ds-header__nav a:hover { color: var(--text-primary, #2a1f17); }
.ds-header__nav .ds-header__cta { box-sizing: border-box; min-height: 44px; padding: 0 20px; white-space: nowrap; border: 1px solid var(--primary, #4e6b48); border-radius: var(--control-radius, 2px); background: var(--primary, #4e6b48); color: var(--on-primary, #fffaf2); }
.ds-header__nav .ds-header__cta:hover { background: var(--primary-hover, #445e3f); border-color: var(--primary-hover, #445e3f); color: var(--on-primary, #fffaf2); }
.ds-header__nav a:focus-visible { outline: 2px solid var(--focus-ring, #2a1f17); outline-offset: 2px; }

.ds-progress-block { font-family: var(--font-sans-stack, 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif); max-width: 420px; }
.ds-progress__labels { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 8px; font-size: 13px; line-height: 1.38; color: var(--text-secondary, #66554a); }
.ds-progress__value { color: var(--text-primary, #2a1f17); font-variant-numeric: tabular-nums; }
.ds-progress { box-sizing: border-box; height: 6px; overflow: hidden; border-radius: var(--pill-radius, 999px); background: var(--surface-muted, #e8dcc8); }
.ds-progress__bar { height: 100%; border-radius: inherit; background: var(--primary, #4e6b48); transition: width 400ms cubic-bezier(0.16, 1, 0.3, 1); }
